import {test,expect} from 'bun:test'
import {readFile} from 'node:fs/promises'
const sha=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex');
const path='.superpowers/m78-interrupted-session-observe.ts',expected='628a36b97462a8b3c048993b1157cd033eec9a586d3628cf839cd20baa99614c';
const source=await readFile(path,'utf8');expect(sha(source)).toBe(expected);
const body=source.split('\n').filter(l=>!l.startsWith('import ')).join('\n');const js=new Bun.Transpiler({loader:'ts'}).transformSync(body);const AsyncFunction=Object.getPrototypeOf(async()=>{}).constructor;
async function run(change:Record<string,any>={}){const calls:any[]=[];let output:any=null,closed=false,connected=false;const input={operatorId:'/root',operatorDatabaseUrl:'fixture-only',accounts:['manager1','manager2','member','outsider'].map((role,i)=>({role,id:'78000000-0000-4000-8000-00000000000'+i})),...change.input};const columns=['id','user_id','created_at','updated_at'].map(column_name=>({table_name:'sessions',column_name,data_type:column_name.endsWith('_at')?'timestamp with time zone':'uuid'}));columns.push({table_name:'refresh_tokens',column_name:'session_id',data_type:'uuid'});const tx={exec:async(sql:string)=>{calls.push({sql});expect(sql).toBe('set transaction isolation level repeatable read read only')},query:async(sql:string,args:any[])=>{calls.push({sql,args});expect(/^select /i.test(sql)).toBe(true);expect(sql).not.toMatch(/select \*|r\.token|access_token|encrypted_password|audit_log_entries/);if(sql.includes('current_database'))return{rows:[{database:'postgres',actor:'postgres',read_only:change.readonly??'on'}]};if(sql.includes('information_schema'))return{rows:change.columns??columns};if(sql.includes('pg_constraint'))return{rows:change.fks??[{child_table:'auth.refresh_tokens',parent_table:'auth.sessions'}]};if(sql.includes('from auth.sessions where'))return{rows:Array.from({length:change.count??1},(_,i)=>({id:'fixture-session-'+i,user_id:args[0],created_at:'2026-09-22T18:49:13Z',updated_at:'2026-09-22T18:49:13Z'}))};if(sql.includes('count(*)'))return{rows:[{session_id:'fixture-session-0',count:'1'}]};throw Error('unexpected query')}};const db={transaction:async(fn:any)=>fn(tx),close:async()=>{closed=true}};
 let error:any=null;try{await new AsyncFunction('readFile','writeFile','connectOperator','hostedDumpEnvironment','Bun','console',js)(async(p:string)=>change.journal?'changed':readFile(p,'utf8'),async(p:string,text:string,opts:any)=>{expect(p).toBe('.superpowers/m78-interrupted-sessions-observed.json');expect(opts.flag).toBe('wx');if(change.existing)throw Error('EEXIST');output=JSON.parse(text)},async()=>{connected=true;return db},()=>{if(change.transport)throw Error('transport')},{CryptoHasher:Bun.CryptoHasher,stdin:{text:async()=>JSON.stringify(input)}},{log:()=>{}})}catch(e){error=e}return{calls,output,error,closed,connected}}
test('read-only synthetic observer projects only four subjects and counts, closes connection and creates exclusive receipt',async()=>{const r=await run();expect(r.error).toBeNull();expect(r.output.observations).toHaveLength(4);expect(r.output.cleanupClaimed).toBe(false);expect(r.output.authenticationWrites).toBe(0);expect(r.closed).toBe(true);expect(r.calls.filter(c=>c.sql.includes('from auth.sessions where'))).toHaveLength(4)})
test('changed parent, malformed roster or transport refuse before connecting',async()=>{for(const change of [{journal:true},{input:{accounts:[]}},{transport:true}]){const r=await run(change);expect(r.error).not.toBeNull();expect(r.connected).toBe(false);expect(r.output).toBeNull()}})
test('non-readonly identity, wrong schema, overflow and reused output fail with connection closed',async()=>{for(const change of [{readonly:'off'},{columns:[]},{count:1001},{existing:true}]){const r=await run(change);expect(r.error).not.toBeNull();expect(r.output).toBeNull();expect(r.closed).toBe(true)}})
test('no actual session foreign key means no refresh query or invented linked count',async()=>{const r=await run({fks:[]});expect(r.error).toBeNull();expect(r.calls.some(c=>c.sql.includes('count(*)'))).toBe(false);expect(r.output.observations.every((o:any)=>o.refreshCounts===null)).toBe(true)})
test('root wrapper pins observer before ENV and DPAPI access and only transfers role/id plus narrow URL via stdin',async()=>{const s=await readFile('.superpowers/m78-private-interrupted-session-observe.ps1','utf8');expect(sha(s)).toBe('5e71f69357d05ca6ea1d22d4f3b619057699e4f6681d570ec74d70936fd111e0');expect(s.indexOf(expected)).toBeLessThan(s.indexOf('[IO.File]::ReadAllLines'));expect(s.indexOf(expected)).toBeLessThan(s.indexOf('::Unprotect'));expect(s).toContain('@{role=$_.role;id=$_.id}');expect(s).toContain('$start.RedirectStandardInput=$true');expect(s).toContain('$start.RedirectStandardError=$true');expect(s).toContain('$start.CreateNoWindow=$true')})

import {readFile,writeFile} from 'node:fs/promises';
import {connectOperator} from '../tools/staging/m77-common';
import {hostedDumpEnvironment} from '../tools/staging/m78-hosted-database';
const sha=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex');
function check(v:unknown):asserts v {if(!v)throw Error('Interrupted session observation refused');}
const roles=['manager1','manager2','member','outsider'];
const original=await readFile('.superpowers/m78-hosted-continuation2.jsonl','utf8');
const diagnostic=await readFile('.superpowers/m78-hosted-continuation2-diagnostics.jsonl','utf8');
check(sha(original)==='3ce68c3fc87e37623326badb88d412f2db36daceacf43060c5849f287a358507');
check(sha(diagnostic)==='8ae88cd344ab1a6376b91a63581c57c9c61c381eb57141e1b6a11ca7647eae08');
const events=original.trimEnd().split('\n').map(line=>JSON.parse(line));
const input=JSON.parse(await Bun.stdin.text());
check(input.operatorId==='/root'&&Object.keys(input).sort().join(',')==='accounts,operatorDatabaseUrl,operatorId');
check(Array.isArray(input.accounts)&&input.accounts.length===4&&new Set(input.accounts.map((a:any)=>a.id)).size===4);
for(const role of roles){const matches=input.accounts.filter((a:any)=>a.role===role);check(matches.length===1&&Object.keys(matches[0]).sort().join(',')==='id,role'&&/^[a-f0-9-]{36}$/.test(matches[0].id));}
hostedDumpEnvironment(input.operatorDatabaseUrl);
const db=await connectOperator(input.operatorDatabaseUrl);
try{
 const result=await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only');
  const identity=(await tx.query<any>("select current_database() database,current_user actor,current_setting('transaction_read_only') read_only,clock_timestamp() observed_at")).rows[0];
  check(identity.database==='postgres'&&identity.actor==='postgres'&&identity.read_only==='on');
  const columns=(await tx.query<any>("select table_name,column_name,data_type from information_schema.columns where table_schema='auth' and table_name in ('sessions','refresh_tokens') order by table_name,ordinal_position")).rows;
  const foreignKeys=(await tx.query<any>("select conname,conrelid::regclass::text as child_table,confrelid::regclass::text as parent_table,pg_get_constraintdef(oid) as definition from pg_constraint where contype='f' and (conrelid='auth.sessions'::regclass or confrelid='auth.sessions'::regclass) order by conname")).rows;
  for(const name of ['id','user_id','created_at','updated_at'])check(columns.some((c:any)=>c.table_name==='sessions'&&c.column_name===name&&c.data_type===(name.endsWith('_at')?'timestamp with time zone':'uuid')));
  const observations=[];
  for(const role of roles){
   const account=input.accounts.find((a:any)=>a.role===role);
   const start=events.find((e:any)=>e.kind==='auth_intent'&&e.data.role===role),end=events.find((e:any)=>e.kind==='auth_outcome'&&e.data.role===role);
   check(start&&end&&end.data.status===200&&end.data.subjectMatched===true);
   const sessions=(await tx.query<any>('select id,user_id,created_at,updated_at from auth.sessions where user_id=$1 order by created_at,id limit 1001',[account.id])).rows;
   check(sessions.length<=1000);
   const refreshCounts=columns.some((c:any)=>c.table_name==='refresh_tokens'&&c.column_name==='session_id'&&c.data_type==='uuid')&&foreignKeys.some((f:any)=>f.child_table==='auth.refresh_tokens'&&f.parent_table==='auth.sessions')?(await tx.query<any>('select r.session_id,count(*)::text as count from auth.refresh_tokens r join auth.sessions s on s.id=r.session_id where s.user_id=$1 group by r.session_id order by r.session_id',[account.id])).rows:null;
   observations.push({role,userId:account.id,requestStart:start.createdAt,responseObserved:end.createdAt,sessions,refreshCounts});
  }
  return {status:'m78_interrupted_sessions_metadata_observed',observedAt:new Date().toISOString(),identity,columns,foreignKeys,observations,applicationWrites:0,authenticationWrites:0,cleanupClaimed:false,journalSha256:sha(original),diagnosticSha256:sha(diagnostic)};
 });
 await writeFile('.superpowers/m78-interrupted-sessions-observed.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({status:result.status,accounts:result.observations.length,sessionCounts:result.observations.map(o=>({role:o.role,count:o.sessions.length})),applicationWrites:0,authenticationWrites:0,cleanupClaimed:false}));
}finally{await db.close();}

param(
  [Parameter(Mandatory=$true)][ValidateSet('observe')][string]$Mode,
  [Parameter(Mandatory=$true)][string[]]$OperationArguments
)
$ErrorActionPreference='Stop'
try {
  $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
  $scriptFull=Join-Path $workspace '.superpowers/m78-interrupted-session-observe.ts'
  if($Mode -ne 'observe' -or $OperationArguments.Count -ne 1 -or $OperationArguments[0] -ne 'read-only'){throw 'argument count'}
  if((Get-FileHash -LiteralPath $scriptFull).Hash.ToLowerInvariant() -cne '628a36b97462a8b3c048993b1157cd033eec9a586d3628cf839cd20baa99614c'){throw 'observer changed'}
  $values=@()
  foreach($line in [IO.File]::ReadAllLines('C:/Users/nimab/Neuvetra/env.json.txt')){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'connection selection'}
  Add-Type -AssemblyName System.Security
  $sealed=[IO.File]::ReadAllBytes('C:/Users/nimab/Neuvetra/m63-runtime/recovery/m63-private-config.json.dpapi')
  $plain=[Security.Cryptography.ProtectedData]::Unprotect($sealed,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
  $private=[Text.Encoding]::UTF8.GetString($plain) | ConvertFrom-Json
  $accounts=@($private.accounts | ForEach-Object { @{role=$_.role;id=$_.id} })
  $payload=@{operatorDatabaseUrl=[string]$values[0];operatorId='/root';accounts=$accounts} | ConvertTo-Json -Depth 6 -Compress
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName='C:/Users/nimab/.bun/bin/bun.exe'
  $start.WorkingDirectory=$workspace
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($scriptFull);$start.ArgumentList.Add($Mode)
  foreach($argument in $OperationArguments){$start.ArgumentList.Add($argument)}
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $process.StandardInput.Write($payload);$process.StandardInput.Close()
  $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync()
  $process.WaitForExit()
  Write-Output $output.Result
  if($process.ExitCode -ne 0){Write-Output 'M78 private database operation failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'M78 private database operation unavailable; sensitive diagnostics withheld.';exit 1}
